namespace ghidra.app.plugin.core.datamgr;

using docking;
using docking.action;
using docking.action;
using ghidra.util;

public class ShowDataTypesTableAction : DockingAction {

	public static readonly string NAME = "Show Data Types Table";

	private DataTypeManagerPlugin plugin;

	ShowDataTypesTableAction(DataTypeManagerPlugin plugin, string menuSubGroup) : base(NAME, plugin.getName())
    {
		this.plugin = plugin;

		setMenuBarData(
			new MenuData(new string[] { NAME }, null, "VeryLast", -1, menuSubGroup));

		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Data_Types_Table"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		plugin.showDataTypesTable();
	}
}
